// Pacenote theme system (redesign, block 1, 2026-11-18).
// One theme = a style (Classic, Roadbook, Broadsheet) x a mode (light, dark). The token VALUES of Roadbook and
// Broadsheet are generated by scripts/gen-theme.py from research/redesign-src/_themes.js into PNTheme+Tokens.swift:
// do not edit them by hand. Classic is hand-written below (it is the look the app had before the redesign).
//
// How it reaches the views:
//  - PN.C.* (PacenoteTheme.swift) stays as the facade: every colour resolves from the current style and the
//    appearance of the view that draws it, so the ~1500 existing uses switch without being touched.
//  - @Environment(\.pnTheme) gives the whole token set (shape, type, motion) for views that need more than colour.
//  - PNThemeModel.style is Observable: a view whose body read PN.C.* or pnTheme redraws when the style changes
//    (Settings > General > Appearance), no restart, no window rebuild. The mode follows NSApp.appearance as before.

import SwiftUI
import AppKit
import Observation

enum PNStyle: String, CaseIterable, Identifiable {
    case classic, roadbook, broadsheet
    var id: String { rawValue }
    /// The style a fresh install starts on (owner, 2026-11-18: Roadbook in the Pacenote build, marked "default").
    static let buildDefault: PNStyle = .roadbook
    init(config value: String) { self = PNStyle(rawValue: value) ?? PNStyle.buildDefault }
}

extension Notification.Name {
    /// Posted (main thread) when the style changes: the tips window (a web view) listens and sets data-style.
    static let pnStyleChanged = Notification.Name("PNStyleChanged")
}

/// The current style. Observable, so SwiftUI bodies that read a theme colour redraw on a change.
final class PNThemeModel: Observable, @unchecked Sendable {
    static let shared = PNThemeModel()
    private let registrar = ObservationRegistrar()
    private var storedStyle: PNStyle = PNStyle.buildDefault
    var style: PNStyle {
        get { registrar.access(self, keyPath: \.style); return storedStyle }
        set {
            guard newValue != storedStyle else { return }
            registrar.withMutation(of: self, keyPath: \.style) { storedStyle = newValue }
            NotificationCenter.default.post(name: .pnStyleChanged, object: nil)
        }
    }
}

/// Faces a style uses. Classic is the system font; the other two are bundled (Resources/Fonts, see PNFonts).
enum PNFace {
    case system, barlowCondensed, barlow, interTight, jetBrainsMono, plexMono
}

enum PNFontRole { case display, text, mono }

/// All tokens of one style in one mode. Colours are 0xRRGGBB; an optional is "none" (transparent).
struct PNTheme {
    let style: PNStyle
    let dark: Bool

    // Surfaces and lines
    let bg, surface, surface2, frame: UInt32
    let ink, ink2, ink3: UInt32
    let rule, ruleStrong, field: UInt32
    // Actions and links
    let accent, onAccent, link: UInt32
    let hlBg: UInt32?
    let hlFg: UInt32
    // The mark
    let markBg: UInt32?
    let markFg, markDot: UInt32
    /// The blue start dot of the spinner (the Classic blue, lighter on a dark ground without a plate).
    let spDot: UInt32
    // States
    let ready, readyText: UInt32
    let notready, notreadyText: UInt32
    let nrBg: UInt32?
    let rec, recText: UInt32
    let answer, docs, edge: UInt32
    // Legacy roles kept for PN.C: turn, on-me, danger, the two pending oranges
    let turn, onMe, danger, pending, pendingFill: UInt32

    // Shape
    let caps: Bool
    let radiusButton, radiusCard: CGFloat
    let ruleHeavy: CGFloat
    let statusSquare: Bool
    // Type
    let display, text, mono: PNFace
    let bSize, bigBtn, tabSize, secSize, titleSize, bigNum: CGFloat
    let bTrack, secTrack, lblTrack, dTrack: CGFloat      // em
    // Motion (nil = smooth, n = n hard steps)
    let ringSteps, drawSteps, barSteps: Int?
    let barRound: Bool

    static func resolve(_ style: PNStyle, dark: Bool) -> PNTheme {
        switch (style, dark) {
        case (.classic, false): return .classicLight
        case (.classic, true): return .classicDark
        case (.roadbook, false): return .roadbookLight
        case (.roadbook, true): return .roadbookDark
        case (.broadsheet, false): return .broadsheetLight
        case (.broadsheet, true): return .broadsheetDark
        }
    }

    /// Looks up a face for a role.
    func face(_ role: PNFontRole) -> PNFace {
        switch role { case .display: return display; case .text: return text; case .mono: return mono }
    }

    /// A font for a role. Bundled faces are picked by weight (their static files), Classic uses the system font.
    func font(_ role: PNFontRole, _ size: CGFloat, _ weight: Font.Weight = .regular) -> Font {
        let f = face(role)
        if f == .system {
            return role == .mono ? .system(size: size, weight: weight, design: .monospaced) : .system(size: size, weight: weight)
        }
        _ = PNFonts.once
        return .custom(PNFonts.postScriptName(f, weight), size: size)
    }

    /// Text on a fill in the link colour (a small "Connect" pill): white in Classic, onAccent in Roadbook, white or the dark ground in Broadsheet.
    var onLink: UInt32 { style == .classic ? 0xFFFFFF : (style == .broadsheet && dark ? edge : onAccent) }

    /// Letter case of buttons, labels and section heads (Roadbook sets them in capitals).
    func cased(_ s: String) -> String { caps ? s.uppercased() : s }

    // MARK: Classic (the look before the redesign; the values are the old PN.C ones)
    private static func classic(dark d: Bool) -> PNTheme {
        func p(_ l: UInt32, _ dk: UInt32) -> UInt32 { d ? dk : l }
        return PNTheme(
            style: .classic, dark: d,
            bg: p(0xF5F5F7, 0x1E1E20), surface: p(0xFFFFFF, 0x2C2C2E), surface2: p(0xEEEEF1, 0x3A3A3C), frame: p(0xC7C7CC, 0x48484A),
            ink: p(0x1D1D1F, 0xF5F5F7), ink2: p(0x3A3A3C, 0xC7C7CC), ink3: p(0x6E6E73, 0x98989D),
            rule: p(0xE5E5EA, 0x3A3A3C), ruleStrong: p(0xC7C7CC, 0x636366), field: p(0x86868B, 0x636366),
            accent: 0x0A6CFF, onAccent: 0xFFFFFF, link: p(0x0A6CFF, 0x4D9DFF),
            hlBg: nil, hlFg: p(0x1D1D1F, 0xF5F5F7),
            markBg: nil, markFg: p(0x1D1D1F, 0xF5F5F7), markDot: p(0x0A6CFF, 0x4D9DFF), spDot: p(0x0A6CFF, 0x4D9DFF),
            ready: p(0x15803D, 0x4CD964), readyText: p(0x15803D, 0x4CD964),
            // "not ready": light = text in ink on an orange plate, dark = orange text without a plate (Tokens r3, notready-plate)
            notready: p(0xE8590C, 0xFFB340), notreadyText: p(0x1D1D1F, 0xFFB340), nrBg: d ? nil : 0xE8590C,
            rec: p(0xFF3B30, 0xFF453A), recText: p(0xD70015, 0xFF6961),
            answer: p(0x0058B0, 0x64B5FF), docs: p(0x7D3C9E, 0xD29BF5), edge: p(0xFFFFFF, 0x1E1E20),
            turn: p(0x1A7431, 0x4CD964), onMe: p(0x9A4600, 0xFFB340), danger: p(0xC4000F, 0xFF6961),
            pending: p(0xE8590C, 0xFFA940), pendingFill: p(0xFF8A00, 0xFFA826),
            caps: false, radiusButton: 7, radiusCard: 14, ruleHeavy: 1, statusSquare: false,
            display: .system, text: .system, mono: .system,
            bSize: 14, bigBtn: 16, tabSize: 15, secSize: 13, titleSize: 26, bigNum: 72,
            bTrack: 0, secTrack: 0, lblTrack: 0, dTrack: 0,
            ringSteps: nil, drawSteps: nil, barSteps: nil, barRound: true)
    }
    static let classicLight = classic(dark: false)
    static let classicDark = classic(dark: true)
}

// MARK: - Environment

extension EnvironmentValues {
    /// The token set for the style in use and this view's appearance. Reads the observable style, so the view redraws on a change.
    var pnTheme: PNTheme { PNTheme.resolve(PNThemeModel.shared.style, dark: colorScheme == .dark) }
}

// MARK: - Colours from tokens

extension Color {
    /// A colour that takes its value from the current style and the appearance it is drawn in.
    /// The style is read when this is called (inside a body: tracked), the appearance when it is drawn.
    static func pnRole(_ get: @escaping (PNTheme) -> UInt32) -> Color {
        let style = PNThemeModel.shared.style
        return Color(nsColor: NSColor(name: nil) { appearance in
            let dark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            return NSColor(pnHex: get(PNTheme.resolve(style, dark: dark)))
        })
    }
    static func pnRole(optional get: @escaping (PNTheme) -> UInt32?, fallback: Color = .clear) -> Color {
        let style = PNThemeModel.shared.style
        return Color(nsColor: NSColor(name: nil) { appearance in
            let dark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            guard let v = get(PNTheme.resolve(style, dark: dark)) else { return NSColor.clear }
            return NSColor(pnHex: v)
        })
    }
    init(pnHex v: UInt32) {
        self.init(.sRGB, red: Double((v >> 16) & 0xFF) / 255, green: Double((v >> 8) & 0xFF) / 255, blue: Double(v & 0xFF) / 255, opacity: 1)
    }
}

extension NSColor {
    convenience init(pnHex v: UInt32) {
        self.init(srgbRed: CGFloat((v >> 16) & 0xFF) / 255, green: CGFloat((v >> 8) & 0xFF) / 255, blue: CGFloat(v & 0xFF) / 255, alpha: 1)
    }
}

// MARK: - Fonts

/// The bundled faces (Resources/Fonts, SIL OFL): registered for this process at start, so no install is needed.
/// Barlow and Barlow Condensed have no Cyrillic: Ukrainian text in Roadbook falls back to the system font for those faces.
enum PNFonts {
    /// Registered once on first use: the shot modes (--shots, --render-sheet-shots) have their own app delegate and never
    /// reach AppDelegate's launch, so the custom faces fell back to the system font there (review 18.11).
    static let once: Void = register()

    static func register() {
        let fm = FileManager.default
        var dirs: [URL] = []
        if let r = Bundle.main.resourceURL { dirs.append(r.appendingPathComponent("Fonts")) }
        // swift run / debug build outside the bundle: the sources' Resources folder
        dirs.append(URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Resources/Fonts"))
        for dir in dirs {
            guard let files = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil) else { continue }
            for f in files where f.pathExtension.lowercased() == "ttf" {
                var err: Unmanaged<CFError>?
                CTFontManagerRegisterFontsForURL(f as CFURL, .process, &err)      // already registered: ignored
            }
            return
        }
    }

    /// PostScript name of the static file for a face and weight (the nearest weight the family ships).
    static func postScriptName(_ face: PNFace, _ w: Font.Weight) -> String {
        func rank(_ w: Font.Weight) -> Int {
            switch w {
            case .ultraLight, .thin, .light, .regular: return 400
            case .medium: return 500
            case .semibold: return 600
            case .bold: return 700
            case .heavy: return 800
            default: return 900     // .black
            }
        }
        let r = rank(w)
        func pick(_ have: [Int]) -> Int { have.min(by: { abs($0 - r) < abs($1 - r) }) ?? 400 }
        func label(_ n: Int) -> String {
            switch n { case 400: return "Regular"; case 500: return "Medium"; case 600: return "SemiBold"
            case 700: return "Bold"; case 800: return "ExtraBold"; default: return "Black" }
        }
        switch face {
        case .system: return ""
        case .barlowCondensed: return "BarlowCondensed-" + label(pick([600, 700, 800]))
        case .barlow: return "Barlow-" + label(pick([400, 500, 600, 700]))
        case .interTight: return "InterTight-" + label(pick([400, 500, 600, 700, 800, 900]))
        case .jetBrainsMono: return "JetBrainsMono-" + label(pick([400, 600]))
        case .plexMono: return "IBMPlexMono-" + label(pick([400, 500]))
        }
    }
}
